729: static int hclge_def_phy_opt(struct mii_bus *mdio_bus, u32 phy_addr,
730: 			     u16 reg_addr, u16 *data,
731: 			     enum hclge_phy_op_code opt_type)
732: {
733: 	int ret;
734: 
735: 	if (opt_type == PHY_OP_READ) {
736: 		ret = mdio_bus->read(mdio_bus, phy_addr, reg_addr);
737: 		if (ret >= 0) {
738: 			*data = (u16)ret;
739: 			ret = 0;
740: 		}
741: 	} else {
742: 		ret = mdio_bus->write(mdio_bus, phy_addr, reg_addr, *data);
