747: static int hclge_phy_reg_opt(struct hclge_dev *hdev,
748: 			     struct hnae3_phy_para *para,
749: 			     enum hclge_phy_op_code opt_type)
750: {
751: 	struct mii_bus *mdio_bus = hdev->hw.mac.mdio_bus;
752: 	u32 phy_addr = hdev->hw.mac.phy_addr;
753: 	bool need_page_select = false;
754: 	u16 cur_page;
755: 	int ret;
756: 
757: 	/* operate flow:
758: 	 * 1 record current page addr
759: 	 * 2 jump to operated page
760: 	 * 3 operate register(read or write)
761: 	 * 4 come back to the page recorded in the first step.
762: 	 */
763: 	mutex_lock(&mdio_bus->mdio_lock);
764: 
765: 	/* check if page select is needed and record current page addr.
766: 	 * no need to change page when read page 0
767: 	 */
768: 	if (opt_type != PHY_OP_READ || para->page != 0) {
769: 		ret = mdio_bus->read(mdio_bus, phy_addr,
770: 				     para->page_select_addr);
771: 		if (ret < 0) {
772: 			dev_err(&hdev->pdev->dev,
773: 				"failed to read current phy %u reg page\n",
774: 				phy_addr);
775: 			mutex_unlock(&mdio_bus->mdio_lock);
776: 			return ret;
777: 		}
778: 		cur_page = (u16)ret;
779: 		need_page_select = cur_page != para->page;
780: 	}
781: 
782: 	/* jump to operated page */
783: 	if (need_page_select) {
784: 		ret = mdio_bus->write(mdio_bus, phy_addr,
785: 				      para->page_select_addr, para->page);
786: 		if (ret < 0) {
787: 			mutex_unlock(&mdio_bus->mdio_lock);
788: 			dev_err(&hdev->pdev->dev,
789: 				"failed to change phy %u page %u to page %u\n",
790: 				phy_addr, cur_page, para->page);
791: 			return ret;
792: 		}
793: 	}
794: 
795: 	/* operate register(read or write) */
796: 	ret = hclge_def_phy_opt(mdio_bus, phy_addr, para->reg_addr, &para->data,
797: 				opt_type);
798: 	if (ret < 0)
799: 		dev_err(&hdev->pdev->dev,
800: 			"failed to %s phy %u page %u reg %u\n, ret = %d",
801: 			opt_type == PHY_OP_READ ? "read" : "write",
802: 			phy_addr, para->page, para->reg_addr, ret);
803: 
804: 	/* come back to the page recorded in the first step. */
805: 	if (need_page_select) {
806: 		ret = mdio_bus->write(mdio_bus, phy_addr,
807: 				      para->page_select_addr, cur_page);
808: 		if (ret < 0)
809: 			dev_err(&hdev->pdev->dev,
810: 				"failed to restore phy %u reg page %u\n",
811: 				phy_addr, cur_page);
812: 	}
813: 
814: 	mutex_unlock(&mdio_bus->mdio_lock);
815: 
816: 	return ret;
817: }
